<style>
#pmc-leak{
  --lk-leaf:#457340; --lk-leaf-bright:#5FA354; --lk-gold:#D7AF33; --lk-gold-soft:#e8c862;
  --lk-cream:#F5F0E8; --lk-muted:rgba(245,240,232,.62); --lk-faint:rgba(245,240,232,.40); --lk-hair:rgba(245,240,232,.09);
  --lk-display:'Clash Display',sans-serif; --lk-body:'Satoshi',sans-serif;
  --lk-mono:'JetBrains Mono',ui-monospace,'SF Mono',Menlo,monospace;
  position:relative; width:100%; color:var(--lk-cream);
  font-family:var(--lk-body); -webkit-font-smoothing:antialiased;
}
#pmc-leak *{margin:0;padding:0;box-sizing:border-box}
/* ===== GRID ===== */
#pmc-leak .lk-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:20px}
#pmc-leak .lk-card{
  position:relative;display:flex;flex-direction:column;padding:30px 26px 34px;border-radius:18px;overflow:hidden;
  background:linear-gradient(180deg, rgba(245,240,232,.05), rgba(245,240,232,.012));
  border:1px solid var(--lk-hair);
  opacity:0;transform:translateY(36px);
  transition:opacity .8s cubic-bezier(.2,.7,.2,1),transform .8s cubic-bezier(.2,.7,.2,1),
             border-color .45s ease,box-shadow .45s ease;
}
#pmc-leak.live .lk-card{opacity:1;transform:translateY(0)}
#pmc-leak.live .lk-card:nth-child(1){transition-delay:.05s}
#pmc-leak.live .lk-card:nth-child(2){transition-delay:.16s}
#pmc-leak.live .lk-card:nth-child(3){transition-delay:.27s}
#pmc-leak.live .lk-card:nth-child(4){transition-delay:.38s}
#pmc-leak .lk-card:hover{
  border-color:rgba(215,175,51,.32);
  box-shadow:0 18px 50px -24px rgba(0,0,0,.8), 0 0 0 1px rgba(215,175,51,.10);
  transform:translateY(-6px);
}
/* draining accent edge - the leak */
#pmc-leak .lk-edge{
  position:absolute;left:0;top:0;bottom:0;width:3px;
  background:linear-gradient(180deg,var(--lk-leaf-bright) 0%,var(--lk-leaf) 35%,var(--lk-gold) 100%);
  background-size:100% 220%;animation:lkDrain 4.5s linear infinite;
  opacity:.7;transition:opacity .4s ease;
}
#pmc-leak .lk-card:hover .lk-edge{opacity:1}
@keyframes lkDrain{from{background-position:0 0}to{background-position:0 -220%}}
/* falling droplet */
#pmc-leak .lk-drip{
  position:absolute;left:0;top:0;width:5px;height:5px;border-radius:50%;
  background:var(--lk-gold-soft);box-shadow:0 0 8px 1px rgba(215,175,51,.6);
  opacity:0;transform:translateX(-1px);
}
#pmc-leak.live .lk-drip{animation:lkFall 4.5s linear infinite}
#pmc-leak .lk-card:hover .lk-drip{animation-duration:2.6s}
#pmc-leak.live .lk-card:nth-child(2) .lk-drip{animation-delay:1.1s}
#pmc-leak.live .lk-card:nth-child(3) .lk-drip{animation-delay:2.2s}
#pmc-leak.live .lk-card:nth-child(4) .lk-drip{animation-delay:3.1s}
@keyframes lkFall{0%{top:14%;opacity:0}12%{opacity:.9}82%{opacity:.85}100%{top:98%;opacity:0}}
/* pool the leak collects in at the base */
#pmc-leak .lk-pool{
  position:absolute;left:-6px;bottom:-8px;width:60px;height:18px;border-radius:50%;
  background:radial-gradient(ellipse,rgba(215,175,51,.4),transparent 70%);
  filter:blur(2px);opacity:.3;transition:opacity .4s ease;
}
#pmc-leak .lk-card:hover .lk-pool{opacity:.7}
/* icon - transparent, no background box, larger */
#pmc-leak .lk-icon{
  margin-bottom:22px;line-height:0;display:flex;align-items:center;justify-content:flex-start;
}
/* ===== ICONS (self-contained) ===== */
#pmc-leak .lk-ico{width:54px;height:54px;display:block;overflow:visible}
#pmc-leak .lk-ico .s{fill:none;stroke:url(#lkLeaf);stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
#pmc-leak .lk-ico .s2{fill:none;stroke:#457340;stroke-width:1.4;stroke-linecap:round;stroke-linejoin:round;opacity:.36}
#pmc-leak .lk-ico .sg{fill:none;stroke:url(#lkGold);stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
#pmc-leak .lk-ico .hl{fill:none;stroke:rgba(245,240,232,0.5);stroke-width:0.8;stroke-linecap:round;opacity:.4}
#pmc-leak .lk-ico .fg{fill:url(#lkGold)}
#pmc-leak .lk-ico .fl{fill:url(#lkLeaf)}
#pmc-leak .lk-ico .field{stroke:#457340;opacity:.14;fill:none;stroke-width:1.1}
#pmc-leak .lk-ico .bloomg{filter:url(#lkBloom)}
#pmc-leak .lk-ico .transient{opacity:0}
/* 01 Local service - storefront */
#pmc-leak .lk-ico.i-shop .glow{transform-box:fill-box;transform-origin:center}
#pmc-leak.live .lk-ico.i-shop .glow{animation:lkShopGlow 2.6s ease-in-out infinite}
#pmc-leak.live .lk-ico.i-shop .sign{animation:lkShopSign 2.6s ease-in-out infinite}
#pmc-leak.live .lk-ico.i-shop .awn{animation:lkShopAwn 3.6s ease-in-out infinite}
@keyframes lkShopGlow{0%,100%{opacity:0}45%{opacity:.42}}
@keyframes lkShopSign{0%,100%{opacity:.4}50%{opacity:.9}}
@keyframes lkShopAwn{0%,100%{opacity:.85}50%{opacity:1}}
/* 02 Clarity - calendar */
#pmc-leak .lk-ico.i-cal .chip{transform-box:fill-box;transform-origin:center}
#pmc-leak .lk-ico.i-cal .focus{transform-box:fill-box;transform-origin:center}
#pmc-leak.live .lk-ico.i-cal .c1{animation:lkChip 1.8s ease-in-out infinite 0s}
#pmc-leak.live .lk-ico.i-cal .c2{animation:lkChip 1.8s ease-in-out infinite .18s}
#pmc-leak.live .lk-ico.i-cal .c3{animation:lkChip 1.8s ease-in-out infinite .36s}
#pmc-leak.live .lk-ico.i-cal .c4{animation:lkChip 1.8s ease-in-out infinite .54s}
#pmc-leak.live .lk-ico.i-cal .focus{animation:lkFocus 2.2s ease-out infinite}
#pmc-leak.live .lk-ico.i-cal .check{animation:lkCheck 2.2s ease-in-out infinite}
@keyframes lkChip{0%,100%{opacity:.45;transform:scale(.82)}50%{opacity:1;transform:scale(1.1)}}
@keyframes lkFocus{0%{opacity:0;transform:scale(.5)}30%{opacity:.9;transform:scale(1)}70%{opacity:.35;transform:scale(1.12)}100%{opacity:0;transform:scale(1.3)}}
@keyframes lkCheck{0%,40%{stroke-dashoffset:11}58%,88%{stroke-dashoffset:0}100%{stroke-dashoffset:11}}
/* 03 Brand & product - brand tag */
#pmc-leak .lk-ico.i-tag .tag{transform-box:view-box;transform-origin:32px 12px}
#pmc-leak .lk-ico.i-tag .mark{transform-box:fill-box;transform-origin:center}
#pmc-leak.live .lk-ico.i-tag .tag{animation:lkTagSwing 3.6s ease-in-out infinite}
#pmc-leak.live .lk-ico.i-tag .mark{animation:lkTagSpark 2.1s ease-in-out infinite}
@keyframes lkTagSwing{0%,100%{transform:rotate(-2.5deg)}50%{transform:rotate(2.5deg)}}
@keyframes lkTagSpark{0%,100%{opacity:.55;transform:scale(.82)}50%{opacity:1;transform:scale(1.12)}}
/* 04 Multi-channel - broadcast */
#pmc-leak .lk-ico.i-cast .wave,#pmc-leak .lk-ico.i-cast .ep,#pmc-leak .lk-ico.i-cast .core{transform-box:fill-box;transform-origin:center}
#pmc-leak.live .lk-ico.i-cast .core{animation:lkCore 1.8s ease-in-out infinite}
#pmc-leak.live .lk-ico.i-cast .v1{animation:lkWave 2.1s ease-out infinite 0s}
#pmc-leak.live .lk-ico.i-cast .v2{animation:lkWave 2.1s ease-out infinite .5s}
#pmc-leak.live .lk-ico.i-cast .v3{animation:lkWave 2.1s ease-out infinite 1s}
#pmc-leak.live .lk-ico.i-cast .e1{animation:lkEp 2.1s ease-in-out infinite .2s}
#pmc-leak.live .lk-ico.i-cast .e2{animation:lkEp 2.1s ease-in-out infinite .55s}
#pmc-leak.live .lk-ico.i-cast .e3{animation:lkEp 2.1s ease-in-out infinite .9s}
#pmc-leak.live .lk-ico.i-cast .e4{animation:lkEp 2.1s ease-in-out infinite 1.25s}
@keyframes lkCore{0%,100%{opacity:.85;transform:scale(.9)}50%{opacity:1;transform:scale(1.12)}}
@keyframes lkWave{0%{opacity:0;transform:scale(.3)}25%{opacity:.85}100%{opacity:0;transform:scale(1)}}
@keyframes lkEp{0%,35%{fill:#071312;transform:scale(1)}55%{fill:#D7AF33;transform:scale(1.4)}100%{fill:#071312;transform:scale(1)}}
#pmc-leak .lk-tag{
  display:flex;align-items:center;gap:9px;font-family:var(--lk-mono);
  font-size:9.5px;font-weight:400;letter-spacing:.1em;text-transform:uppercase;
  color:var(--lk-gold);margin-top:auto;padding-top:16px;
}
#pmc-leak .lk-sq{
  width:8px;height:8px;background:var(--lk-gold);border-radius:1.5px;
  box-shadow:0 0 8px rgba(215,175,51,.7);animation:lkBlip 2.6s ease-in-out infinite;
}
@keyframes lkBlip{0%,100%{opacity:1}50%{opacity:.35}}
#pmc-leak .lk-card h3{
  font-family:var(--lk-display);font-weight:500;letter-spacing:-.01em;
  font-size:24px;line-height:1.02;margin-bottom:18px;color:var(--lk-cream);
}
#pmc-leak .lk-pills{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:22px}
#pmc-leak .lk-pill{
  font-family:var(--lk-mono);font-size:11px;letter-spacing:.06em;color:var(--lk-faint);
  padding:6px 11px;border-radius:8px;border:1px solid var(--lk-hair);
  background:rgba(245,240,232,.02);transition:color .3s ease,border-color .3s ease,background .3s ease;
}
#pmc-leak .lk-card:hover .lk-pill{color:var(--lk-muted);border-color:rgba(245,240,232,.16)}
#pmc-leak .lk-card p{color:var(--lk-muted);font-size:14px;line-height:1.55}
#pmc-leak .lk-card p b{color:var(--lk-cream);font-weight:600}
#pmc-leak .lk-foot{
  margin-top:46px;display:flex;align-items:center;gap:12px;
  font-family:var(--lk-mono);font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:var(--lk-faint);
  opacity:0;animation:lkRise 1s 1.5s ease forwards;
}
#pmc-leak .lk-foot .lk-line{flex:1;height:1px;background:linear-gradient(90deg,var(--lk-hair),transparent)}
@keyframes lkRise{to{opacity:1;transform:translateY(0)}}
@media(max-width:1000px){#pmc-leak .lk-grid{grid-template-columns:repeat(2,1fr);gap:16px}}
@media(max-width:560px){#pmc-leak .lk-grid{grid-template-columns:1fr}}
@media(prefers-reduced-motion:reduce){
  #pmc-leak *{animation:none!important;transition:none!important}
  #pmc-leak .lk-card{opacity:1!important;transform:none!important}
  #pmc-leak .lk-ico .transient{opacity:0!important}
}
</style>
<svg width="0" height="0" style="position:absolute" aria-hidden="true"><defs>
  <linearGradient id="lkLeaf" x1="0" y1="0" x2="0.9" y2="1"><stop offset="0" stop-color="#3A6536"/><stop offset="0.5" stop-color="#5FA354"/><stop offset="1" stop-color="#7FD972"/></linearGradient>
  <linearGradient id="lkGold" x1="0" y1="0" x2="0.9" y2="1"><stop offset="0" stop-color="#BE9426"/><stop offset="0.5" stop-color="#D7AF33"/><stop offset="1" stop-color="#E6C765"/></linearGradient>
  <filter id="lkBloom" x="-120%" y="-120%" width="340%" height="340%"><feGaussianBlur in="SourceGraphic" stdDeviation="1.4" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter>
</defs></svg>
  <div class="lk-grid">
    <!-- CARD 1 - Visibility / i-shop -->
    <div class="lk-card">
      <span class="lk-edge"></span><span class="lk-drip"></span><span class="lk-pool"></span>
      <div class="lk-icon">
        <svg class="lk-ico i-shop" viewBox="0 0 64 64">
          <line class="s2" x1="12" y1="50" x2="52" y2="50"/>
          <rect class="s" x="17" y="24" width="30" height="26"/>
          <line class="hl sign" x1="21" y1="31" x2="43" y2="31"/>
          <rect class="s2" x="20" y="35" width="6.5" height="8"/>
          <rect class="s2" x="37.5" y="35" width="6.5" height="8"/>
          <path class="s" d="M28.5 50 V38 Q28.5 35.5 32 35.5 Q35.5 35.5 35.5 38 V50"/>
          <circle class="fg" cx="34" cy="43.5" r=".8"/>
          <path class="glow transient fg bloomg" d="M28.5 50 V38 Q28.5 35.5 32 35.5 Q35.5 35.5 35.5 38 V50 Z"/>
          <path class="sg awn" d="M14 19 L50 19 L50 23 Q45.5 27.5 41 23 Q36.5 27.5 32 23 Q27.5 27.5 23 23 Q18.5 27.5 14 23 Z"/>
          <line class="sg awn" x1="23" y1="19" x2="23" y2="23" style="stroke-width:1"/>
          <line class="sg awn" x1="32" y1="19" x2="32" y2="23" style="stroke-width:1"/>
          <line class="sg awn" x1="41" y1="19" x2="41" y2="23" style="stroke-width:1"/>
        </svg>
      </div>
      <h3>Hard to find</h3>
      <div class="lk-pills"><span class="lk-pill">Search</span><span class="lk-pill">Maps</span><span class="lk-pill">AI</span></div>
      <p>The business is strong, but the places people check first do not make that obvious. <b>Search, Maps, and recommendations</b> point somewhere else.</p>
      <div class="lk-tag"><span class="lk-sq"></span>Leak: Visibility breaks</div>
    </div>
    <!-- CARD 2 - Clarity / i-cal -->
    <div class="lk-card">
      <span class="lk-edge"></span><span class="lk-drip"></span><span class="lk-pool"></span>
      <div class="lk-icon">
        <svg class="lk-ico i-cal" viewBox="0 0 64 64">
          <rect class="s" x="14" y="18" width="36" height="31" rx="4.5"/>
          <path class="hl" d="M17 18.6 H47"/>
          <line class="s2" x1="14" y1="26" x2="50" y2="26"/>
          <line class="sg" x1="23" y1="13" x2="23" y2="20" style="stroke-width:2"/>
          <line class="sg" x1="41" y1="13" x2="41" y2="20" style="stroke-width:2"/>
          <rect class="chip c1" x="19" y="30" width="6" height="4.5" rx="1.4" fill="#5FA354"/>
          <rect class="chip c2" x="29" y="30" width="6" height="4.5" rx="1.4" fill="#5FA354"/>
          <rect class="chip c3" x="19" y="38" width="6" height="4.5" rx="1.4" fill="#5FA354"/>
          <rect class="chip c4" x="29" y="38" width="6" height="4.5" rx="1.4" fill="url(#lkGold)"/>
          <circle class="focus transient sg" cx="32" cy="40.2" r="6.4" stroke-width="1.4" fill="none"/>
          <polyline class="check sg bloomg" points="38,40 40.5,42.5 45,37" fill="none" stroke-width="2" stroke-dasharray="11"/>
        </svg>
      </div>
      <h3>Hard to understand</h3>
      <div class="lk-pills"><span class="lk-pill">Offer</span><span class="lk-pill">Message</span><span class="lk-pill">Website</span></div>
      <p>People arrive but cannot quickly tell what makes the business different, who it is for, or why it is worth choosing. <b>Interest turns into uncertainty.</b></p>
      <div class="lk-tag"><span class="lk-sq"></span>Leak: Clarity breaks</div>
    </div>
    <!-- CARD 3 - Conversion / i-tag -->
    <div class="lk-card">
      <span class="lk-edge"></span><span class="lk-drip"></span><span class="lk-pool"></span>
      <div class="lk-icon">
        <svg class="lk-ico i-tag" viewBox="0 0 64 64">
          <g class="tag">
            <circle class="hl ring" cx="32" cy="12" r="3.4" fill="none"/>
            <line class="s2" x1="32" y1="15.4" x2="32" y2="18"/>
            <path class="s body" d="M32 17 L41 24 L41 45 Q41 48 38 48 L26 48 Q23 48 23 45 L23 24 Z"/>
            <circle class="s hole" cx="32" cy="23" r="2.2" fill="none"/>
            <path class="fg mark bloomg" d="M32 31 L33.5 34.5 L37 36 L33.5 37.5 L32 41 L30.5 37.5 L27 36 L30.5 34.5 Z"/>
          </g>
        </svg>
      </div>
      <h3>Hard to choose</h3>
      <div class="lk-pills"><span class="lk-pill">Proof</span><span class="lk-pill">Booking</span><span class="lk-pill">Contact</span></div>
      <p>The right customer is interested, but the proof is thin or the next step takes too much work. <b>Interest fades before action.</b></p>
      <div class="lk-tag"><span class="lk-sq"></span>Leak: Conversion breaks</div>
    </div>
    <!-- CARD 4 - Follow-up / i-cast -->
    <div class="lk-card">
      <span class="lk-edge"></span><span class="lk-drip"></span><span class="lk-pool"></span>
      <div class="lk-icon">
        <svg class="lk-ico i-cast" viewBox="0 0 64 64">
          <line class="s2" x1="32" y1="32" x2="18" y2="18"/>
          <line class="s2" x1="32" y1="32" x2="46" y2="18"/>
          <line class="s2" x1="32" y1="32" x2="18" y2="46"/>
          <line class="s2" x1="32" y1="32" x2="46" y2="46"/>
          <circle class="wave v1 transient" cx="32" cy="32" r="11" stroke="url(#lkLeaf)" stroke-width="1.6" fill="none"/>
          <circle class="wave v2 transient" cx="32" cy="32" r="16" stroke="url(#lkLeaf)" stroke-width="1.6" fill="none"/>
          <circle class="wave v3 transient" cx="32" cy="32" r="21" stroke="url(#lkGold)" stroke-width="1.6" fill="none"/>
          <circle class="ep e1" cx="18" cy="18" r="3.4" fill="#071312" stroke="url(#lkLeaf)" stroke-width="1.6"/>
          <circle class="ep e2" cx="46" cy="18" r="3.4" fill="#071312" stroke="url(#lkLeaf)" stroke-width="1.6"/>
          <circle class="ep e3" cx="18" cy="46" r="3.4" fill="#071312" stroke="url(#lkLeaf)" stroke-width="1.6"/>
          <circle class="ep e4" cx="46" cy="46" r="3.4" fill="#071312" stroke="url(#lkLeaf)" stroke-width="1.6"/>
          <circle class="core fg bloomg" cx="32" cy="32" r="4.3"/>
        </svg>
      </div>
      <h3>Hard to follow up</h3>
      <div class="lk-pills"><span class="lk-pill">Leads</span><span class="lk-pill">Pipeline</span><span class="lk-pill">Measurement</span></div>
      <p>Inquiries scatter across inboxes and tools. Follow-up becomes inconsistent, and the business cannot see <b>what is creating real opportunities.</b></p>
      <div class="lk-tag"><span class="lk-sq"></span>Leak: Momentum breaks</div>
    </div>
  </div>
  <div class="lk-foot"><span>Different symptoms. One connected customer journey.</span><span class="lk-line"></span></div>
<script>
(function(){
  var root = document.getElementById('pmc-leak');
  if(!root || root.dataset.lkInit) return;
  root.dataset.lkInit = '1';
  function ignite(){ root.classList.add('live'); }
  if('IntersectionObserver' in window){
    var io = new IntersectionObserver(function(es){
      es.forEach(function(e){ if(e.isIntersecting){ ignite(); io.disconnect(); } });
    },{threshold:.2});
    io.observe(root);
  } else { ignite(); }
  window.addEventListener('load',function(){
    var r = root.getBoundingClientRect();
    if(r.top < window.innerHeight*0.85 && !root.classList.contains('live')){ ignite(); }
  });
})();
</script>
</div>
