{"label":"embed-3","action":"get_settings","result":[{"status":"success","message":"Settings retrieved","data":{"type":"all_raw_settings","total_matches":4,"matches":[{"key":"domId","value":""},{"key":"visibility","value":true},{"key":"code","value":"<div id="pmc-install">
<style>
#pmc-install{
  --pi-bg:#040D0D; --pi-leaf:#457340; --pi-leaf-bright:#5FA354; --pi-leaf-glow:#76CC6A;
  --pi-gold:#D7AF33; --pi-gold-bright:#E6C765; --pi-cream:#F5F0E8;
  --pi-t62:rgba(245,240,232,.62); --pi-muted:rgba(245,240,232,.42);
  --pi-border:rgba(245,240,232,.08); --pi-border-2:rgba(245,240,232,.15);
  --pi-disp:'Clash Display',sans-serif; --pi-sans:'Satoshi',system-ui,sans-serif;
  --pi-mono:'JetBrains Mono',ui-monospace,monospace; --pi-ease:cubic-bezier(.16,1,.3,1);
  position:relative; width:100%; color:var(--pi-cream); font-family:var(--pi-sans); -webkit-font-smoothing:antialiased;
}
#pmc-install *{box-sizing:border-box;margin:0;padding:0}
#pmc-install .frows{display:flex;flex-direction:column;gap:12px}
#pmc-install .frow{
  position:relative;border:1px solid var(--pi-border);border-radius:16px;background:rgba(10,26,24,.5);
  overflow:hidden;opacity:0;transform:translateY(20px);
  transition:border-color .3s var(--pi-ease),background .3s var(--pi-ease),opacity .7s var(--pi-ease),transform .7s var(--pi-ease);
}
#pmc-install.live .frow{opacity:1;transform:none}
#pmc-install.live .frow:nth-child(2){transition-delay:.07s}
#pmc-install.live .frow:nth-child(3){transition-delay:.14s}
#pmc-install.live .frow:nth-child(4){transition-delay:.21s}
#pmc-install .frow:hover,#pmc-install .frow.open{border-color:rgba(95,163,84,.4);background:rgba(12,33,30,.7)}
