#pmc-install .it b{font-family:var(--pi-sans);font-weight:700;font-size:13.5px;color:var(--pi-cream);display:block;line-height:1.3;margin-bottom:2px}
#pmc-install .it span{font-family:var(--pi-sans);font-weight:400;font-size:12.5px;color:var(--pi-t62);line-height:1.45;display:block}
@media(max-width:600px){
  #pmc-install .frow-head{gap:16px;padding:18px 18px}
