<script>
(function(){
  var root=document.getElementById('pmc-install');
  if(!root||root.dataset.piInit)return; root.dataset.piInit='1';
  var rows=Array.prototype.slice.call(root.querySelectorAll('[data-frow]'));
  function setOpen(row,open){
    row.classList.toggle('open',open);
    var d=row.querySelector('.frow-d'); if(d) d.style.display=open?'block':'none';
  }
  rows.forEach(function(row){
    var head=row.querySelector('.frow-head');
    head.addEventListener('click',function(){
      var wasOpen=row.classList.contains('open');
      rows.forEach(function(r){setOpen(r,false);});
      if(!wasOpen) setOpen(row,true);
    });
  });
  if(rows[0]) setOpen(rows[0],true);
  function ignite(){ root.classList.add('live'); }
  if('IntersectionObserver' in window){
    var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){ignite();io.disconnect();}});},{threshold:.15});
    io.observe(root);
  } else { ignite(); }
  window.addEventListener('load',function(){
    var r=root.getBoundingClientRect();
    if(r.top<window.innerHeight*0.9 && !root.classList.contains('live')){ ignite(); }
  });
})();
</script>
