<style>
#pmc-system {
  /* Core Palette */
  --gold: #D7AF33;
  --gold-glow: rgba(215, 175, 51, 0.15);
  --gold-bright: rgba(230, 199, 101, 1);
  --leaf: #5FA354;
  --leaf-glow: rgba(95, 163, 84, 0.15);
  --leaf-bright: rgba(118, 204, 106, 1);
  --cream: #F5F0E8;

  /* Surfaces & Lines */
  --bg-surface: rgba(10, 18, 17, 0.4);
  --bg-surface-hover: rgba(15, 28, 26, 0.6);
  --border-subtle: rgba(245, 240, 232, 0.06);
  --border-strong: rgba(245, 240, 232, 0.12);
  --text-muted: rgba(245, 240, 232, 0.4);

  /* Easing */
  --ease-spring: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-flow: cubic-bezier(0.4, 0, 0.2, 1);

  position: relative;
  max-width: 1060px;
  margin: 0 auto;
  padding: 40px clamp(16px, 4vw, 40px);
  font-family: 'Satoshi', -apple-system, BlinkMacSystemFont, sans-serif;
  color: var(--cream);
  overflow: hidden;
}
#pmc-system * { box-sizing: border-box; }
/* Grid Decorators */
#pmc-system .sd-fig {
  position: absolute;
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  letter-spacing: 0.2em;
  color: var(--text-muted);
  text-transform: uppercase;
  z-index: 0;
}
#pmc-system .sd-fig.tl { top: 16px; left: clamp(16px, 4vw, 40px); }
#pmc-system .sd-fig.br { bottom: 16px; right: clamp(16px, 4vw, 40px); }
#pmc-system .sd-corner {
  position: absolute;
  width: 12px;
  height: 12px;
  border: 1px solid var(--text-muted);
  opacity: 0.3;
}
#pmc-system .sd-corner.tl { top: 8px; left: 8px; border-right: none; border-bottom: none; }
#pmc-system .sd-corner.tr { top: 8px; right: 8px; border-left: none; border-bottom: none; }
#pmc-system .sd-corner.bl { bottom: 8px; left: 8px; border-right: none; border-top: none; }
#pmc-system .sd-corner.br { bottom: 8px; right: 8px; border-left: none; border-top: none; }
/* 01. Input Cards */
#pmc-system .sd-cards {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-top: 24px;
  position: relative;
  z-index: 2;
}
#pmc-system .sd-card {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: flex-start;
  text-align: left;
  padding: 28px 24px;
  border-radius: 16px;
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.2), inset 0 1px 0 rgba(255, 255, 255, 0.05);
  transition: transform 0.6s var(--ease-spring), background 0.6s var(--ease-spring), border-color 0.6s var(--ease-spring);
  overflow: hidden;
}
#pmc-system .sd-card::before {
  content: "";
  position: absolute;
  inset: 0;
  /* always-on leaf glow pooled behind the live pulse / label - turns dead space into a powered node */
  background: radial-gradient(72% 60% at 16% 28%, rgba(95, 163, 84, 0.13), transparent 60%);
  opacity: 0.9;
  transition: opacity 0.6s var(--ease-spring);
  pointer-events: none;
}
#pmc-system .sd-card:hover {
  transform: translateY(-6px) scale(1.01);
  background: var(--bg-surface-hover);
  border-color: rgba(215, 175, 51, 0.3);
  box-shadow: 0 20px 40px -10px rgba(0, 0, 0, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.1);
}
#pmc-system .sd-card:hover::before { opacity: 1; }
#pmc-system .sd-card:hover .sd-chip {
  background: radial-gradient(120% 120% at 50% 18%, rgba(215, 175, 51, 0.22), rgba(11, 22, 20, 0.5) 72%) padding-box,
              linear-gradient(180deg, rgba(215, 175, 51, 0.6), rgba(215, 175, 51, 0.12)) border-box;
  color: var(--gold-bright);
  transform: scale(1.05) translateY(-2px);
  box-shadow: 0 0 32px -6px rgba(215, 175, 51, 0.42), inset 0 1px 0 rgba(255, 255, 255, 0.1);
}
#pmc-system .sd-badge {
  position: absolute;
  top: 14px;
  right: 16px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  letter-spacing: 0.1em;
  color: var(--text-muted);
  transition: color 0.4s ease;
}
#pmc-system .sd-card:hover .sd-badge { color: var(--gold); }
#pmc-system .sd-chip {
  width: 58px;
  height: 58px;
  margin: 0 auto 18px;
  border-radius: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
  /* light-catch chip (matches the install modules + engine border) with a soft leaf glow */
  background: radial-gradient(120% 120% at 50% 18%, rgba(95, 163, 84, 0.16), rgba(11, 22, 20, 0.55) 72%) padding-box,
              linear-gradient(180deg, rgba(245, 240, 232, 0.24), rgba(245, 240, 232, 0.05)) border-box;
  border: 1px solid transparent;
  box-shadow: 0 0 26px -8px rgba(95, 163, 84, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  transition: all 0.5s var(--ease-spring);
}
/* Live signal pulse - replaces the channel icon: a leaf core with continuously expanding sonar rings */
#pmc-system .sd-pulse {
  position: relative;
  width: 7px;
  height: 7px;
  flex: none;
  border-radius: 50%;
  background: var(--gold-bright);
  box-shadow: 0 0 11px 2px var(--gold-glow);
  transition: background 0.5s var(--ease-spring), box-shadow 0.5s var(--ease-spring);
}
#pmc-system .sd-pulse::before,
#pmc-system .sd-pulse::after {
  content: "";
  position: absolute;
  inset: -1px;
  border-radius: 50%;
  border: 1.5px solid var(--gold-bright);
  opacity: 0;
  animation: sd-ping 2.8s var(--ease-flow) infinite;
}
#pmc-system .sd-pulse::after { animation-delay: 1.4s; }
#pmc-system .sd-card:nth-child(even) .sd-pulse::before { animation-delay: 0.7s; }
#pmc-system .sd-card:nth-child(even) .sd-pulse::after { animation-delay: 2.1s; }
#pmc-system .sd-card:hover .sd-pulse {
  background: var(--gold-bright);
  box-shadow: 0 0 16px 3px var(--gold-glow);
}
#pmc-system .sd-card:hover .sd-pulse::before,
#pmc-system .sd-card:hover .sd-pulse::after { border-color: var(--gold-bright); }
@keyframes sd-ping {
  0% { transform: scale(1); opacity: 0.7; }
  70% { opacity: 0; }
  100% { transform: scale(2.6); opacity: 0; }
}
#pmc-system .sd-ct {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 9px;
  letter-spacing: 0.2em;
  color: var(--gold);
  text-transform: uppercase;
  margin-bottom: 14px;
}
#pmc-system .sd-name-row {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 10px;
}
#pmc-system .sd-name {
  font-family: 'Clash Display', sans-serif;
  font-weight: 500;
  font-size: clamp(16px, 1.5vw, 18px);
  line-height: 1.2;
  margin: 0 0 8px;
  min-height: 2.4em;
  color: var(--cream);
  letter-spacing: 0.02em;
}
#pmc-system .sd-sub {
  font-family: 'JetBrains Mono', monospace;
  font-size: 9px;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  text-transform: uppercase;
  line-height: 1.6;
}
/* 02. The Manifold (Data Flow) */
#pmc-system .sd-manifold {
  position: relative;
  height: 72px;
  margin: -2px auto;
  z-index: 1;
}
#pmc-system .sd-drop {
  position: absolute;
  top: 0;
  width: 1px;
  height: 36px;
  background: linear-gradient(to bottom, var(--border-subtle), var(--border-strong));
}
#pmc-system .sd-bus {
  position: absolute;
  top: 36px;
  height: 1px;
  background: var(--border-strong);
  box-shadow: 0 0 8px rgba(255, 255, 255, 0.05);
}
#pmc-system .sd-node {
  position: absolute;
  top: 34px;
  left: 50%;
  transform: translateX(-50%);
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--gold-bright);
  box-shadow: 0 0 12px 2px var(--gold-glow);
}
#pmc-system .sd-stem {
  position: absolute;
  top: 36px;
  left: 50%;
  transform: translateX(-50%);
  width: 1px;
  height: 36px;
  background: linear-gradient(to bottom, var(--border-strong), var(--gold-glow));
}
/* Light Packet Animation */
#pmc-system .sd-packet {
  position: absolute;
  left: 50%;
  top: 0;
  width: 2px;
  height: 12px;
  margin-left: -1px;
  border-radius: 4px;
  background: var(--gold-bright);
  box-shadow: 0 0 10px 2px var(--gold);
  animation: sd-flow 2.4s var(--ease-flow) infinite;
  opacity: 0;
}
@keyframes sd-flow {
  0% { top: 0px; height: 4px; opacity: 0; transform: scaleY(1); }
  10% { opacity: 1; }
  50% { top: 18px; height: 16px; opacity: 1; transform: scaleY(1.5); }
  90% { opacity: 1; }
  100% { top: 36px; height: 4px; opacity: 0; transform: scaleY(1); }
}
/* 03. Engine Core (CRM) */
#pmc-system .sd-core {
  position: relative;
  max-width: 520px;
  margin: 0 auto;
  padding: 32px 40px;
  border-radius: 20px;
  background: rgba(8, 14, 13, 0.7);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid rgba(215, 175, 51, 0.2);
  box-shadow:
    0 24px 50px -20px rgba(0, 0, 0, 0.8),
    inset 0 1px 0 rgba(255, 255, 255, 0.05),
    inset 0 0 40px rgba(215, 175, 51, 0.05);
  z-index: 2;
}
#pmc-system .sd-core::after {
  content: "";
  position: absolute;
  inset: -1px;
  border-radius: 20px;
  padding: 1px;
  background: linear-gradient(135deg, rgba(215, 175, 51, 0.5) 0%, rgba(215, 175, 51, 0.05) 50%, rgba(215, 175, 51, 0.2) 100%);
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
}
#pmc-system .sd-core-glow {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 120%;
  height: 120%;
  transform: translate(-50%, -50%);
  background: radial-gradient(circle, var(--gold-glow) 0%, transparent 60%);
  z-index: -1;
  pointer-events: none;
  animation: sd-breathe 4s ease-in-out infinite;
}
@keyframes sd-breathe {
  0%, 100% { opacity: 0.4; transform: translate(-50%, -50%) scale(0.95); }
  50% { opacity: 0.8; transform: translate(-50%, -50%) scale(1.05); }
}
#pmc-system .sd-core-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
}
#pmc-system .sd-live {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  letter-spacing: 0.15em;
  color: var(--leaf);
  text-transform: uppercase;
}
#pmc-system .sd-live i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--leaf-bright);
  box-shadow: 0 0 10px var(--leaf-bright);
  animation: sd-blink 2s ease-in-out infinite;
}
@keyframes sd-blink { 0%, 100% { opacity: 1; } 50% { opacity: 0.2; } }
#pmc-system .sd-engine {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  letter-spacing: 0.15em;
  color: var(--gold);
  text-transform: uppercase;
}
#pmc-system .sd-core-name {
  font-family: 'Clash Display', sans-serif;
  font-weight: 500;
  font-size: clamp(28px, 3vw, 36px);
  line-height: 1;
  text-align: center;
  color: var(--cream);
  letter-spacing: 0.01em;
}
#pmc-system .sd-core-tag {
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  letter-spacing: 0.15em;
  color: var(--text-muted);
  text-transform: uppercase;
  text-align: center;
  margin-top: 10px;
}
/* Precision Data Bars (Replaced EQ) */
#pmc-system .sd-data-grid {
  display: flex;
  justify-content: center;
  align-items: flex-end;
  gap: 6px;
  height: 24px;
  margin: 24px 0 20px;
}
#pmc-system .sd-data-grid i {
  width: 3px;
  border-radius: 2px;
  background: var(--gold-bright);
  box-shadow: 0 0 8px var(--gold-glow);
  transform-origin: bottom;
  animation: sd-process 1.5s var(--ease-spring) infinite;
}
@keyframes sd-process {
  0%, 100% { transform: scaleY(0.2); opacity: 0.4; }
  50% { transform: scaleY(1); opacity: 1; }
}
#pmc-system .sd-caps {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px 12px;
  padding-top: 20px;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
}
#pmc-system .sd-caps span {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  letter-spacing: 0.12em;
  color: var(--text-muted);
  text-transform: uppercase;
  transition: color 0.3s ease;
}
#pmc-system .sd-core:hover .sd-caps span { color: rgba(245, 240, 232, 0.7); }
#pmc-system .sd-caps span+span::before {
  content: "·";
  margin-right: 12px;
  color: var(--gold-glow);
}
/* 04. Output Stem */
#pmc-system .sd-stem2 {
  position: relative;
  width: 1px;
  height: 48px;
  margin: 0 auto;
  background: linear-gradient(to bottom, rgba(215, 175, 51, 0.3), rgba(95, 163, 84, 0.4));
  z-index: 1;
}
#pmc-system .sd-packet.leaf {
  background: var(--leaf-bright);
  box-shadow: 0 0 12px 2px var(--leaf);
  animation: sd-flow-leaf 2s var(--ease-flow) infinite;
  animation-delay: 1.2s;
}
@keyframes sd-flow-leaf {
  0% { top: 0px; height: 4px; opacity: 0; transform: scaleY(1); }
  10% { opacity: 1; }
  50% { top: 24px; height: 16px; opacity: 1; transform: scaleY(1.5); }
  90% { opacity: 1; }
  100% { top: 48px; height: 4px; opacity: 0; transform: scaleY(1); }
}
#pmc-system .sd-arrow {
  display: block;
  width: 8px;
  height: 8px;
  margin: -5px auto 0;
  border-right: 1.5px solid var(--leaf-bright);
  border-bottom: 1.5px solid var(--leaf-bright);
  transform: rotate(45deg);
  box-shadow: 2px 2px 4px rgba(95, 163, 84, 0.3);
}
/* 05. The Output */
#pmc-system .sd-out {
  position: relative;
  max-width: 420px;
  margin: 16px auto 0;
  text-align: center;
  padding: 24px 32px;
  border-radius: 16px;
  border: 1px solid rgba(95, 163, 84, 0.3);
  background: rgba(10, 20, 18, 0.6);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  box-shadow:
    0 16px 40px -10px rgba(0, 0, 0, 0.5),
    inset 0 1px 0 rgba(255, 255, 255, 0.05),
    0 0 40px -15px var(--leaf-glow);
  transition: transform 0.6s var(--ease-spring), box-shadow 0.6s var(--ease-spring);
}
#pmc-system .sd-out:hover {
  transform: translateY(-4px);
  box-shadow: 0 20px 50px -10px rgba(0, 0, 0, 0.6), inset 0 1px 0 rgba(255, 255, 255, 0.05), 0 0 50px -10px rgba(95, 163, 84, 0.25);
}
#pmc-system .sd-out-tag {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  letter-spacing: 0.2em;
  color: var(--leaf-bright);
  text-transform: uppercase;
  margin-bottom: 12px;
}
#pmc-system .sd-out-name {
  font-family: 'Clash Display', sans-serif;
  font-weight: 500;
  font-size: clamp(20px, 2.5vw, 24px);
  line-height: 1.1;
  color: var(--cream);
  letter-spacing: 0.01em;
}
#pmc-system .sd-out-sub {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  letter-spacing: 0.1em;
  color: var(--text-muted);
  text-transform: uppercase;
  margin-top: 12px;
}
/* Responsive */
@media(max-width: 860px) {
  #pmc-system .sd-cards { grid-template-columns: repeat(2, 1fr); gap: 16px; }
  /* Hide desktop manifold to prevent responsive breaks, replace with simple connector */
  #pmc-system .sd-manifold .sd-drop,
  #pmc-system .sd-manifold .sd-bus,
  #pmc-system .sd-manifold .sd-node { display: none; }
  #pmc-system .sd-manifold { height: 40px; }
  #pmc-system .sd-stem { top: 0; height: 40px; }
  @keyframes sd-flow {
    0% { top: 0px; height: 4px; opacity: 0; }
    50% { top: 20px; height: 16px; opacity: 1; }
    100% { top: 40px; height: 4px; opacity: 0; }
  }
}
@media(max-width: 520px) {
  #pmc-system .sd-card { padding: 24px 16px 20px; }
  #pmc-system .sd-chip { width: 50px; height: 50px; margin-bottom: 16px; }
  #pmc-system .sd-chip svg { width: 30px; height: 30px; }

  /* Compact Tree CRM panel - the dominant element on mobile.
     Reduce padding, font, internal heights so the caps row stops
     forcing a tall second line into the output panel below. */
  #pmc-system .sd-core { padding: 22px 18px; }
  #pmc-system .sd-core-top { margin-bottom: 14px; }
  #pmc-system .sd-core-name { font-size: 24px; }
  #pmc-system .sd-core-tag { font-size: 10px; margin-top: 6px; }
  #pmc-system .sd-data-grid { height: 18px; margin: 14px 0 12px; }
  #pmc-system .sd-caps { gap: 4px 10px; padding-top: 12px; }
  #pmc-system .sd-caps span { font-size: 9px; letter-spacing: 0.06em; }
  #pmc-system .sd-caps span + span::before { margin-right: 8px; }

  /* Strengthen the connector between the operating layer and its output.
     1px line at .3 opacity was invisible on mobile, making the two
     panels read as stacked-on-top instead of system-and-output. */
  #pmc-system .sd-stem2 {
    width: 2px;
    height: 56px;
    background: linear-gradient(to bottom, rgba(215, 175, 51, 0.55), rgba(95, 163, 84, 0.65));
  }
  #pmc-system .sd-arrow {
    width: 10px;
    height: 10px;
    margin: -7px auto 0;
    border-right-width: 2px;
    border-bottom-width: 2px;
  }

  /* Output panel: tighter padding so it does not feel double-heavy
     next to the now-leaner Tree CRM panel above. */
  #pmc-system .sd-out { margin-top: 8px; padding: 20px 22px; }
  #pmc-system .sd-out-name { font-size: 20px; }
}
@media(prefers-reduced-motion: reduce) {
  #pmc-system * { animation: none !important; transition: none !important; }
}
