{"label":"embed-5","action":"get_settings","result":[{"status":"success","message":"Settings retrieved","data":{"type":"all_raw_settings","total_matches":4,"matches":[{"key":"domId","value":""},{"key":"visibility","value":true},{"key":"code","value":"<div id="pmc-engine">
<style>
#pmc-engine{
  --pe-leaf:#457340; --pe-leaf-bright:#5f9a55; --pe-gold:#D7AF33; --pe-gold-soft:#e8c862;
  --pe-cream:#F5F0E8; --pe-muted:rgba(245,240,232,.62); --pe-faint:rgba(245,240,232,.40); --pe-hair:rgba(245,240,232,.10);
  --pe-display:'Clash Display',sans-serif; --pe-body:'Satoshi',sans-serif; --pe-mono:'JetBrains Mono',monospace;
  position:relative; width:100%; color:var(--pe-cream);
  font-family:var(--pe-body); -webkit-font-smoothing:antialiased;
}
#pmc-engine *{margin:0;padding:0;box-sizing:border-box}

/* ===== LAYOUT ===== */
#pmc-engine .pe-layout{display:flex;align-items:flex-start}
#pmc-engine .pe-funnel-col{flex:0 0 46%;position:relative}

/* funnel */
#pmc-engine .pe-funnel{position:relative;height:450px}
#pmc-engine .pe-bands{position:absolute;inset:0}
#pmc-engine .pe-band{
  position:absolute;left:0;right:0;height:150px;
  opacity:0;transform:scale(.94);transform-origin:top center;
  transition:opacity .7s cubic-bezier(.2,.7,.2,1),transform .7s cubic-bezier(.2,.7,.2,1);
}
#pmc-engine.live .pe-band{opacity:1;transform:scale(1)}
#pmc-engine .pe-band.pe-b1{top:0;clip-path:polygon(0 0,100% 0,93% 100%,7% 100%);
  background:linear-gradient(180deg,rgba(95,154,85,.24),rgba(69,115,64,.11));
  border-top:1.5px solid rgba(95,154,85,.85);transition-delay:.1s}
#pmc-engine .pe-band.pe-b2{top:150px;clip-path:polygon(7% 0,93% 0,86% 100%,14% 100%);
  background:linear-gradient(180deg,rgba(82,135,72,.20),rgba(150,150,60,.12));
  border-top:1.5px solid rgba(138,168,74,.85);transition-delay:.28s}
#pmc-engine .pe-band.pe-b3{top:300px;clip-path:polygon(14% 0,86% 0,79% 100%,21% 100%);
  background:linear-gradient(180deg,rgba(215,175,51,.24),rgba(215,175,51,.10));
  border-top:1.5px solid rgba(215,175,51,.9);transition-delay:.46s}

/* spout */
#pmc-engine .pe-spout{
  position:absolute;top:450px;left:0;right:0;height:48px;
  clip-path:polygon(21% 0,79% 0,60% 100%,40% 100%);
  background:linear-gradient(180deg,rgba(215,175,51,.16),rgba(215,175,51,.03));
  opacity:0;transition:opacity .6s .7s ease;
}
#pmc-engine.live .pe-spout{opacity:1}
#pmc-engine .pe-spout-glow{
  position:absolute;top:492px;left:50%;transform:translateX(-50%);
  width:120px;height:30px;border-radius:50%;
  background:radial-gradient(ellipse,rgba(215,175,51,.42),transparent 70%);
  opacity:0;filter:blur(2px);
}
#pmc-engine.live .pe-spout-glow{animation:peEmit 3s 1.1s ease-in-out infinite}
@keyframes peEmit{0%,100%{opacity:.16;transform:translateX(-50%) scale(.85)}50%{opacity:.5;transform:translateX(-50%) scale(1.12)}}

/* vertical down-flow arrows */
#pmc-engine .pe-downflow{
  position:absolute;top:0;bottom:0;left:50%;transform:translateX(-50%);
  width:16px;overflow:hidden;z-index:2;opacity:0;transition:opacity .8s .6s ease;
  -webkit-mask-image:linear-gradient(180deg,#000 0%,#000 6%,transparent 10%,transparent 24%,#000 29%,#000 38%,transparent 43%,transparent 57%,#000 62%,#000 71%,transparent 76%,transparent 90%,#000 94%,#000 100%);
          mask-image:linear-gradient(180deg,#000 0%,#000 6%,transparent 10%,transparent 24%,#000 29%,#000 38%,transparent 43%,transparent 57%,#000 62%,#000 71%,transparent 76%,transparent 90%,#000 94%,#000 100%);
}
#pmc-engine.live .pe-downflow{opacity:.34}
#pmc-engine .pe-downflow-track{display:flex;flex-direction:column;gap:14px;align-items:center;animation:peMarchDown 1.4s linear infinite}
#pmc-engine .pe-downflow-track i{
  flex:0 0 auto;width:7px;height:7px;transform:rotate(135deg);
  border-top:1.4px solid var(--pe-gold-soft);border-right:1.4px solid var(--pe-gold-soft);
}
@keyframes peMarchDown{from{transform:translateY(-21px)}to{transform:translateY(0)}}

/* band labels */
#pmc-engine .pe-labels{position:absolute;inset:0;z-index:3;pointer-events:none}
#pmc-engine .pe-label{
  position:absolute;left:0;right:0;height:150px;display:flex;flex-direction:column;
  align-items:center;justify-content:center;text-align:center;padding:0 16%;
  opacity:0;transform:translateY(10px);transition:opacity .6s ease,transform .6s ease;
}
#pmc-engine.live .pe-label{opacity:1;transform:translateY(0)}
#pmc-engine .pe-label.pe-l1{top:0;transition-delay:.35s}
#pmc-engine .pe-label.pe-l2{top:150px;transition-delay:.53s}
#pmc-engine .pe-label.pe-l3{top:300px;transition-delay:.71s}
#pmc-engine .pe-days{font-family:var(--pe-mono);font-weight:600;font-size:10.5px;letter-spacing:.18em;text-transform:uppercase;margin-bottom:7px}
#pmc-engine .pe-label.pe-l1 .pe-days{color:var(--pe-leaf-bright)}
#pmc-engine .pe-label.pe-l2 .pe-days{color:#b8c25a}
#pmc-engine .pe-label.pe-l3 .pe-days{color:var(--pe-gold)}
#pmc-engine .pe-label h2{
  font-family:var(--pe-display);font-weight:500;letter-spacing:-.01em;line-height:1;
  font-size:clamp(18px,2.2vw,25px);text-shadow:0 2px 18px rgba(4,13,13,.6);color:var(--pe-cream);
}
#pmc-engine .pe-label h2 .pe-amp{color:var(--pe-gold);font-weight:500}
#pmc-engine .pe-label.pe-l3 h2 .pe-amp{color:var(--pe-cream)}
#pmc-engine .pe-num{
  font-family:var(--pe-mono);font-weight:600;font-size:13px;letter-spacing:.1em;
  color:rgba(245,240,232,.35);margin-bottom:4px;
}

/* ===== RIGHT: connectors + cards ===== */
#pmc-engine .pe-cards-col{flex:1;display:flex;flex-direction:column;gap:0;position:relative;padding-left:8px}
#pmc-engine .pe-cards-col::before{
  content:"";position:absolute;left:34px;top:75px;height:300px;width:2px;
  background:linear-gradient(180deg,var(--pe-leaf-bright),var(--pe-gold));
  transform:scaleY(0);transform-origin:top;transition:transform 1.1s .5s cubic-bezier(.65,0,.2,1);
  opacity:.5;
}
#pmc-engine.live .pe-cards-col::before{transform:scaleY(1)}
#pmc-engine .pe-row{display:flex;align-items:center;min-height:150px}
#pmc-engine .pe-link{flex:0 0 108px;position:relative;height:40px;display:flex;align-items:center}
#pmc-engine .pe-node{
  position:absolute;left:28px;top:50%;width:14px;height:14px;border-radius:50%;
  transform:translate(-50%,-50%);background:#040D0D;border:2px solid var(--pe-faint);
  transition:border-color .4s,box-shadow .4s;z-index:2;
}
#pmc-engine .pe-node::after{content:"";position:absolute;inset:3px;border-radius:50%;background:transparent;transition:background .4s}
#pmc-engine .pe-r1 .pe-node.pe-on{border-color:var(--pe-leaf-bright);box-shadow:0 0 0 4px rgba(95,154,85,.12),0 0 16px rgba(95,154,85,.5)}
#pmc-engine .pe-r1 .pe-node.pe-on::after{background:var(--pe-leaf-bright)}
#pmc-engine .pe-r2 .pe-node.pe-on{border-color:#b8c25a;box-shadow:0 0 0 4px rgba(150,160,70,.14),0 0 16px rgba(150,160,70,.5)}
#pmc-engine .pe-r2 .pe-node.pe-on::after{background:#b8c25a}
#pmc-engine .pe-r3 .pe-node.pe-on{border-color:var(--pe-gold);box-shadow:0 0 0 4px rgba(215,175,51,.14),0 0 18px rgba(215,175,51,.6)}
#pmc-engine .pe-r3 .pe-node.pe-on::after{background:var(--pe-gold)}

/* right-flowing arrows from node into card */
#pmc-engine .pe-connect{
  position:absolute;left:42px;right:0;height:12px;overflow:hidden;
  opacity:0;transition:opacity .6s ease;
  -webkit-mask-image:linear-gradient(90deg,transparent,#000 22%,#000 100%);
          mask-image:linear-gradient(90deg,transparent,#000 22%,#000 100%);
}
#pmc-engine.live .pe-connect{opacity:1}
#pmc-engine.live .pe-r1 .pe-connect{transition-delay:.7s}
#pmc-engine.live .pe-r2 .pe-connect{transition-delay:.88s}
#pmc-engine.live .pe-r3 .pe-connect{transition-delay:1.06s}
#pmc-engine .pe-connect-track{display:flex;gap:14px;align-items:center;width:max-content;animation:peMarch 1.3s linear infinite;opacity:.8}
#pmc-engine .pe-connect-track i{flex:0 0 auto;width:6px;height:6px;transform:rotate(45deg);
  border-top:1.5px solid var(--pe-leaf-bright);border-right:1.5px solid var(--pe-leaf-bright)}
#pmc-engine .pe-r2 .pe-connect-track i{border-color:#b8c25a}
#pmc-engine .pe-r3 .pe-connect-track i{border-color:var(--pe-gold)}
@keyframes peMarch{from{transform:translateX(0)}to{transform:translateX(-20px)}}

#pmc-engine .pe-ccard{
  flex:1;position:relative;padding:18px 22px;border-radius:14px;
  background:linear-gradient(180deg,rgba(245,240,232,.045),rgba(245,240,232,.01));
  border:1px solid var(--pe-hair);overflow:hidden;
  opacity:0;transform:translateX(28px);
  transition:opacity .7s cubic-bezier(.2,.7,.2,1),transform .7s cubic-bezier(.2,.7,.2,1),border-color .4s;
}
#pmc-engine.live .pe-ccard{opacity:1;transform:translateX(0)}
#pmc-engine.live .pe-r1 .pe-ccard{transition-delay:.55s}
#pmc-engine.live .pe-r2 .pe-ccard{transition-delay:.73s}
#pmc-engine.live .pe-r3 .pe-ccard{transition-delay:.91s}
#pmc-engine .pe-ccard::before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--pe-leaf-bright)}
#pmc-engine .pe-r2 .pe-ccard::before{background:#b8c25a}
#pmc-engine .pe-r3 .pe-ccard::before{background:var(--pe-gold)}
#pmc-engine .pe-ccard:hover{border-color:rgba(245,240,232,.22)}
#pmc-engine .pe-r3 .pe-ccard:hover{border-color:rgba(215,175,51,.35)}
#pmc-engine .pe-tag{
  display:flex;align-items:center;gap:9px;font-family:var(--pe-mono);font-size:10.5px;font-weight:600;letter-spacing:.18em;
  text-transform:uppercase;color:var(--pe-muted);margin-bottom:13px;
}
#pmc-engine .pe-tag::before{content:"";width:16px;height:1px;background:var(--pe-leaf-bright)}
#pmc-engine .pe-r2 .pe-tag::before{background:#b8c25a}
#pmc-engine .pe-r3 .pe-tag::before{background:var(--pe-gold)}
#pmc-engine ul{list-style:none;display:grid;grid-template-columns:1fr 1fr;gap:8px 20px}
#pmc-engine li{
  display:flex;gap:9px;font-size:13px;line-height:1.38;color:var(--pe-muted);
  opacity:0;transform:translateX(-8px);transition:opacity .45s,transform .45s;
}
#pmc-engine.live li{opacity:1;transform:translateX(0)}
#pmc-engine.live .pe-r1 li{transition-delay:calc(.8s + var(--i) * .07s)}
#pmc-engine.live .pe-r2 li{transition-delay:calc(.98s + var(--i) * .07s)}
#pmc-engine.live .pe-r3 li{transition-delay:calc(1.16s + var(--i) * .07s)}
#pmc-engine li .pe-chev{flex-shrink:0;margin-top:4px;width:6px;height:6px;transform:rotate(45deg);
  border-top:1.5px solid var(--pe-leaf-bright);border-right:1.5px solid var(--pe-leaf-bright);
