(function(){
  var root = document.getElementById('pmc-engine');
  if(!root || root.dataset.peInit) return;
  root.dataset.peInit = '1';
  var reduce = window.matchMedia && matchMedia('(prefers-reduced-motion:reduce)').matches;
  var nodes = [].slice.call(root.querySelectorAll('.pe-node'));
  // fill the down-flow funnel stream
  var df = root.querySelector('.pe-downflow-track');
  if(df){ for(var i=0;i<60;i++){ df.appendChild(document.createElement('i')); } }
  // fill the right-flowing connector streams
  [].slice.call(root.querySelectorAll('.pe-connect-track')).forEach(function(t){
    for(var i=0;i<26;i++){ t.appendChild(document.createElement('i')); }
  });
  function ignite(){
    root.classList.add('live');
    if(reduce){ nodes.forEach(function(n){ n.classList.add('pe-on'); }); return; }
    nodes.forEach(function(n,i){ setTimeout(function(){ n.classList.add('pe-on'); }, 650 + i*460); });
  }
  if('IntersectionObserver' in window){
    var io = new IntersectionObserver(function(es){
      es.forEach(function(e){ if(e.isIntersecting){ ignite(); io.disconnect(); } });
    },{threshold:.3});
    io.observe(root);
  } else {
    ignite();
  }
  window.addEventListener('load',function(){
    var r = root.getBoundingClientRect();
    if(r.top < window.innerHeight*0.85 && !root.classList.contains('live')){ ignite(); }
  });
})();
